function customArc(cx, cy, size, rSpan, rotation)
{
	const c = shuffle(COLS);
	const cbk = 0.55228474983;

	const ro = size - rSpan;
	const ri = rSpan;
	const w = ro - ri;

	noStroke();
	fill(c[0]);
	push();
	translate(cx, cy);
	rotate(rotation);
	translate(-size / 2, -size /2);
	beginShape();
	vertex(ro, 0);
	bezierVertex(ro, cbk * ro, cbk * ro , ro, 0, ro);
	vertex(0, ri);
	bezierVertex(ri * cbk, ri, ri, ri * cbk, ri, 0);
	endShape(CLOSE);	
	push();
	drawingContext.clip();


	const dNum = DIV_NUM;
	const rn = random();

	if(rn < 0.33)
	{
		const span = (size - rSpan * 2) * 2 / dNum;
		let dia = ro * 2;
		for(let i = 0; i < dNum; i++)
		{
			fill(c[i % c.length]);
			circle(0,0, dia - span * i);
		}
	}else if(rn < 0.66)
	{
		const span = PI /2 / dNum;
		let dia = ro * 2;
		for(let i = 0 ; i < dNum; i++)
		{
			fill(c[i % c.length]);
			arc(0, 0, dia, dia, i * span, (i + 1) * span);
		}
	}else
	{
		fill(c[1]);
		const span = size / dNum;
		const sizeMul = 0.8;
		for(let yi = 0; yi <= dNum; yi++)
		for(let xi = 0; xi <= dNum; xi++)
		{
			circle(xi * span, yi * span, span * sizeMul);
		}
	}
	pop();
	pop();
}


function customRect(cx, cy, size, wid, rotation)
{
	const c = shuffle(COLS);
	const dNum = DIV_NUM;

	rectMode(CENTER);
	noStroke();
	fill(c[0]);

	push();
	translate(cx, cy);
	rotate(rotation);
	rect(0, 0, size, wid);

	push();
	drawingContext.clip();
	translate(-size / 2, -size / 2);

	const rn = random();
	if(rn < 0.33)
	{
		const span = size / dNum;
		rectMode(CORNER);
		for(let i = 0; i < dNum; i++)
		{
			if(rn < 0.15){
				fill(c[i % c.length]);
				rect(i * span, 0, span, size);
			}
			else{
				fill(c[1]);
				triangle(i * span, (size - wid) / 2, (i + 1) * span, (size - wid) / 2, i * span, size - (size - wid) / 2);
			}
		}
		rectMode(CENTER);
	}
	else if(rn < 0.66)
	{
		const span = wid / dNum;
		rectMode(CORNER);
		for(let i = 0; i < dNum; i++)
		{
			fill(c[i % c.length]);
			rect(0, i * span + (size - wid) / 2, size, span);
		}
		rectMode(CENTER);
	}
	else
	{
		fill(c[1]);
		const span = size / dNum;
		const sizeMul = 0.8;
		for(let yi = 0; yi <= dNum; yi++)
			for(let xi = 0; xi <= dNum; xi++)
				circle(xi * span, yi * span, span * sizeMul);
	}
	pop();
	pop();

}


